<script setup lang="ts">import type{CaseFile}from'../types/archive';defineProps<{rows:CaseFile[];loading:boolean}>();const emit=defineEmits<{submit:[id:string]}>();const labels:Record<string,string>={draft:'草稿',pending_review:'待审核',archived:'已归档',borrowed:'借阅中',sealed:'已封存',destroyed:'已销毁'}</script>
<template><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="case_number" label="案卷号" width="160"/><el-table-column prop="title" label="标题" min-width="220"/><el-table-column prop="year" label="年度" width="90"/><el-table-column prop="security_level" label="密级" width="110"/><el-table-column label="状态" width="110"><template #default="s"><el-tag>{{labels[s.row.status]}}</el-tag></template></el-table-column><el-table-column prop="version" label="版本" width="80"/><el-table-column label="操作" width="140"><template #default="s"><el-button v-if="s.row.status==='draft'" link type="primary" @click="emit('submit',s.row.id)">提交审核</el-button><router-link :to="`/cases/${s.row.id}`">详情</router-link></template></el-table-column></el-table></template>
